<body><%		switch ($action) {						case "view" :				print_from($IDPuntoVenta,$Fecha);			break;						default :				print_from("");			break;				} // End switch /*******************************************************************************************		funcion Listar*******************************************************************************************/function print_from($IDPuntoVenta="", $Fecha=""){ Global $dblink,$total_records,$row,$numtoshow,$Nivel,$IVA,$Mes_array,$FechaDesde, $FechaHasta; //require( "Reportes/Calc.php" ); //$Calendario = new Date_Calc;%>		<table width="100%">				<tr>		<td>			<table width='100%' align='left' border="0" cellspacing="0" cellpadding="2" class="bordertable">				<form action="./" name="frmPuntoVenta" method="post" name="Moviles">						<tr>							<td valign="middle"><img src="images/calendar_edit.png" border="0" alt=""></td>							<td  align='left' valign='middle' class="nav">															Desde	<input readonly type="text" name="FechaDesde" class="input" value="<?=fecha()?>" size="10">								<script language="JavaScript1.2">									<!--										if (!document.layers)											document.write("<img src=jscripts/imagescalendar/cal.gif onmouseover=this.style.cursor='hand' onclick='popUpCalendar(this, document.frmPuntoVenta.FechaDesde,\"yyyy-mm-dd\")' width=16 height=16 border=0>")																//-->								</script>							</td>							<td align="left" valign="middle" class="nav">																Hasta	<input readonly type="text" name="FechaHasta" class="input" value="<?=fecha()?>" size="10">								<script language="JavaScript1.2">									<!--										if (!document.layers)											document.write("<img src=jscripts/imagescalendar/cal.gif onmouseover=this.style.cursor='hand' onclick='popUpCalendar(this, document.frmPuntoVenta.FechaHasta,\"yyyy-mm-dd\")' width=16 height=16 border=0>")																//-->								</script>								<input type="hidden" name="mod" value="VentasVendedor"><input type="hidden" name="action" value="view"></td>							<td  align='left' valign='middle' class="nav"></td>							<td align="left" valign="middle" class="nav"></td>							<td align="left" valign="middle" class="nav">								<input type="submit" value="Ver Reporte" name="submit" class="submit">							</td>						</tr>				</form>			</table>			</td>		</tr>				<br>		<br>		<%		if(!empty( $FechaDesde ) && !empty( $FechaHasta ) ){		%>		<tr>		<td>&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;				<table width="100%" border="0" align="center" cellspacing="1" cellpadding="0" bgcolor="#345487">					<form name="frm" action="<?=$PHP_SELF?>" method="post" onsubmit="return Evalua(document.frm)">						<tr>							<td class="maintitle" valign="middle">								Reporte Ventas Empleados <b>Desde :</b> <?=formatofecha($FechaDesde)?>  <b>Hasta :</b> <?=formatofecha($FechaHasta)?> 							</td>						</tr>						<? 															$qry_empleado = db_query( $sql_empleados = "SELECT IDEmpleado, CONCAT(Nombre,' ',Apellidos) as Nombre, Cedula FROM Empleado");						$i = 0;						while( $r_empleado = db_fetch_array( $qry_empleado ) )						{													$array_empleados[$i] = $r_empleado;														$sql_ventasadmin = " SELECT SUM(VE.Venta) as ValorTotal, VE.IDPuntoVenta, VE.Cargo 												FROM VentasEmpleado VE, Factura F												WHERE VE.IDEmpleado = '$r_empleado[IDEmpleado]' 												AND FIND_IN_SET( 'Administrador', VE.Cargo) > 0 												AND VE.IDFactura = F.IDFactura												AND F.IDPuntoVenta = VE.IDPuntoVenta 												AND DATE_FORMAT( F.FechaFactura,'%Y-%c-%d' ) >= DATE_FORMAT( '$FechaDesde', '%Y-%c-%d' )												AND DATE_FORMAT( F.FechaFactura,'%Y-%c-%d' ) <= DATE_FORMAT( '$FechaHasta', '%Y-%c-%d' )												GROUP BY VE.IDPuntoVenta;";														$qry_ventasadmin = db_query( $sql_ventasadmin );							$j = 0;							while( $r_ventasadmin = db_fetch_array( $qry_ventasadmin ) )							{								$array_ventasadmin[$r_empleado[IDEmpleado]][$j] = $r_ventasadmin;								$j++;							}//end while																										$sql_ventasvendedor = " SELECT SUM(VE.Venta) as ValorTotal, VE.IDPuntoVenta, VE.Cargo 												FROM VentasEmpleado VE, Factura F												WHERE VE.IDEmpleado = '$r_empleado[IDEmpleado]' 												AND FIND_IN_SET( 'Empleado', VE.Cargo) > 0 												AND VE.IDFactura = F.IDFactura												AND F.IDPuntoVenta = VE.IDPuntoVenta  												AND DATE_FORMAT( F.FechaFactura,'%Y-%c-%d' ) >= DATE_FORMAT( '$FechaDesde','%Y-%c-%d' )												AND DATE_FORMAT( F.FechaFactura,'%Y-%c-%d' ) <= DATE_FORMAT( '$FechaHasta' ,'%Y-%c-%d' )												GROUP BY VE.IDPuntoVenta";														$qry_ventasvendedor = db_query( $sql_ventasvendedor );							$j = 0;							while( $r_ventasvendedor = db_fetch_array( $qry_ventasvendedor ) )							{								$array_ventasvendedor[$r_empleado[IDEmpleado]][$j] = $r_ventasvendedor;								$j++;							}//end while														$i++;						}//end while( $r_empleado = db_fetch_array( $qry_empleado ) )												$qry_puntosventa = db_query( "SELECT IDPuntoVenta, Nombre FROM PuntoVenta" );						while( $r_puntodeventa = db_fetch_array( $qry_puntosventa ) )						{							$array_punto[$r_puntodeventa['IDPuntoVenta']] = $r_puntodeventa['Nombre'];						}//end while punto venta				?>						<tr>							<td class="mainbg">								<table width="100%" border="0" cellspacing="1" cellpadding="1">									<tr>										<td class="titlemedium" align="center" nowrap>Cedula</td>										<td class="titlemedium" align="center" nowrap>Nombre</td>										<td class="titlemedium" align="center" nowrap>Tipo</td>										<td class="titlemedium" align="center" nowrap>Punto Venta</td>										<td class="titlemedium" align="center" nowrap>Valor Vendido</td>									</tr>				<?						//print_r($array_ventasadmin);						foreach( $array_empleados as $key => $valor )						{ 							$class = repetition()?"row2":"row1";														foreach( $array_ventasadmin[$valor['IDEmpleado']] as $llave => $venta  )							{				?>									<tr>										<td class="<?=$class?>" align="center" nowrap><?=$valor['Cedula']?></td>										<td class="<?=$class?>" align="center" nowrap><?=$valor['Nombre']?></td>										<td class="<?=$class?>" align="center" nowrap><?=$venta['Cargo']?></td>										<td class="<?=$class?>" align="center" nowrap><?echo $array_punto[ $venta['IDPuntoVenta'] ];?></td>										<td class="<?=$class?>" align="right" nowrap><?=number_format( $venta['ValorTotal'], 2); $total +=  $venta['ValorTotal']?></td>									</tr>				<?							}//end foreach( $array_ventasadmin[$valor['IDEmpleado']] as $llave => $venta  )							foreach( $array_ventasvendedor[$valor['IDEmpleado']] as $llave => $venta  )							{				?>									<tr>										<td class="<?=$class?>" align="center" nowrap><?=$valor['Cedula']?></td>										<td class="<?=$class?>" align="center" nowrap><?=$valor['Nombre']?></td>										<td class="<?=$class?>" align="center" nowrap><?=$venta['Cargo']?></td>										<td class="<?=$class?>" align="center" nowrap><?=$array_punto[ $venta['IDPuntoVenta'] ];?></td>										<td class="<?=$class?>" align="right" nowrap><?=number_format( $venta['ValorTotal'], 2) ; $total +=  $venta['ValorTotal']?></td>									</tr>				<?							}//end foreach( $array_ventasvendedor[$valor['IDEmpleado']] as $llave => $venta  )													}//end foreach( $r_facturas as $key => $valor )				?>								</table>							</td>						</tr>					</form>				</table>			</td>	</tr>	<% 	 } // END if(!empty($IDEmpresa))	%>	</table>	<%						}// Enf function print()	%></body>